<?php
require_once __DIR__.'/attachment_common.php';
try{$uid=att_user();$d=json_decode(file_get_contents('php://input'),true)?:[];$project=att_clean($d['project_id']??'',50);att_access($pdo,$project,$uid);$id=(int)($d['attachment_id']??0);$entity=(int)($d['entity_id']??0);$type=att_clean($d['entity_type']??'',30);$allowed=['requirement','use_case','task','issue','milestone','asset','risk','user_story'];if(!$id||!$entity||!in_array($type,$allowed,true))throw new Exception('Verknüpfungsdaten fehlen.');$check=$pdo->prepare('SELECT 1 FROM project_attachments WHERE id=? AND project_id=?');$check->execute([$id,$project]);if(!$check->fetchColumn())throw new Exception('Anhang nicht gefunden.');$q=$pdo->prepare('INSERT INTO attachment_links(attachment_id,entity_type,entity_id,entity_key,entity_title) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE entity_key=VALUES(entity_key),entity_title=VALUES(entity_title)');$q->execute([$id,$type,$entity,att_clean($d['entity_key']??'',100),att_clean($d['entity_title']??'',255)]);att_json(['success'=>true]);}catch(Throwable $e){att_json(['success'=>false,'error'=>$e->getMessage()],400);}
